/**
 * Circuit Breaker Pattern Implementation
 * Prevents cascading failures by failing fast when a service is down
 */

import { logger } from './monitoring';
import { sanitizeLogMessage } from './sanitization';

export function isCircuitBreakerOpenError(error: unknown): boolean {
  if (!(error instanceof Error)) {
    return false;
  }

  return /Circuit breaker .+ is OPEN/.test(error.message);
}

export enum CircuitState {
  CLOSED = 'CLOSED', // Normal operation
  OPEN = 'OPEN', // Failing fast
  HALF_OPEN = 'HALF_OPEN', // Testing if service recovered
}

interface CircuitBreakerConfig {
  failureThreshold: number; // Number of failures before opening
  successThreshold: number; // Number of successes to close from half-open
  timeout: number; // Time in ms before attempting recovery
  monitoringPeriod: number; // Time window for failure counting
}

interface CircuitBreakerStats {
  failures: number;
  successes: number;
  lastFailureTime: number;
  lastSuccessTime: number;
  state: CircuitState;
}

const DEFAULT_CONFIG: CircuitBreakerConfig = {
  failureThreshold: 5,
  successThreshold: 1,
  timeout: 5000, // 5 seconds before attempting a recovery probe
  monitoringPeriod: 60000, // 1 minute
};

export class CircuitBreaker {
  private state: CircuitState = CircuitState.CLOSED;
  private failures = 0;
  private successes = 0;
  private lastFailureTime = 0;
  private lastSuccessTime = 0;
  private lastStateChange = Date.now();
  private windowStart = Date.now();
  private config: CircuitBreakerConfig;
  private name: string;

  constructor(name: string, config: Partial<CircuitBreakerConfig> = {}) {
    this.name = name;
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Execute a function with circuit breaker protection
   */
  async execute<T>(fn: () => Promise<T>): Promise<T> {
    if (this.state === CircuitState.OPEN) {
      if (this.shouldAttemptReset()) {
        this.state = CircuitState.HALF_OPEN;
        logger.info(`Circuit breaker ${sanitizeLogMessage(this.name)} entering HALF_OPEN state`);
      } else {
        throw new Error(`Circuit breaker ${sanitizeLogMessage(this.name)} is OPEN`);
      }
    }

    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (error) {
      this.onFailure();
      throw error;
    }
  }

  /**
   * Handle successful execution
   */
  private onSuccess(): void {
    this.lastSuccessTime = Date.now();

    if (this.state === CircuitState.HALF_OPEN) {
      this.successes++;

      if (this.successes >= this.config.successThreshold) {
        this.state = CircuitState.CLOSED;
        this.failures = 0;
        this.successes = 0;
        this.lastFailureTime = 0;
        this.lastStateChange = Date.now();
        logger.info(`Circuit breaker ${sanitizeLogMessage(this.name)} closed after recovery`);
      }
    }
    else {
      // In CLOSED state the threshold counts consecutive failures. A successful
      // request proves the dependency recovered, so clear prior failures.
      this.failures = 0;
      this.windowStart = Date.now();
      this.lastFailureTime = 0;
    }
  }

  /**
   * Handle failed execution
   */
  private onFailure(): void {
    const now = Date.now();
    // Reset failure count if outside the monitoring window
    if (now - this.windowStart > this.config.monitoringPeriod) {
      this.failures = 0;
      this.windowStart = now;
    }

    this.failures++;
    this.lastFailureTime = now;
    this.successes = 0;

    logger.warning(`Circuit breaker ${sanitizeLogMessage(this.name)} failure`, {
      failures: this.failures,
      threshold: this.config.failureThreshold,
    });

    if (this.state === CircuitState.HALF_OPEN) {
      this.state = CircuitState.OPEN;
      this.lastStateChange = Date.now();
      logger.error(`Circuit breaker ${sanitizeLogMessage(this.name)} reopened after failed recovery`);
    } else if (this.failures >= this.config.failureThreshold) {
      this.state = CircuitState.OPEN;
      this.lastStateChange = Date.now();
      logger.error(`Circuit breaker ${sanitizeLogMessage(this.name)} opened due to failures`, {
        failures: this.failures,
      });
    }
  }

  /**
   * Check if enough time has passed to attempt reset
   */
  private shouldAttemptReset(): boolean {
    return Date.now() - this.lastStateChange >= this.config.timeout;
  }

  /**
   * Get current circuit breaker stats
   */
  getStats(): CircuitBreakerStats {
    return {
      failures: this.failures,
      successes: this.successes,
      lastFailureTime: this.lastFailureTime,
      lastSuccessTime: this.lastSuccessTime,
      state: this.state,
    };
  }

  /**
   * Manually reset the circuit breaker
   */
  reset(): void {
    this.state = CircuitState.CLOSED;
    this.failures = 0;
    this.successes = 0;
    this.lastFailureTime = 0;
    this.lastSuccessTime = 0;
    this.lastStateChange = Date.now();
    this.windowStart = Date.now();
    logger.info(`Circuit breaker ${sanitizeLogMessage(this.name)} manually reset`);
  }

  /**
   * Get current state
   */
  getState(): CircuitState {
    return this.state;
  }
}

/**
 * Circuit breaker registry for managing multiple breakers
 */
class CircuitBreakerRegistry {
  private breakers = new Map<string, CircuitBreaker>();

  /**
   * Get or create a circuit breaker
   */
  get(name: string, config?: Partial<CircuitBreakerConfig>): CircuitBreaker {
    const existingBreaker = this.breakers.get(name);
    if (existingBreaker) { return existingBreaker; }
    const breaker = new CircuitBreaker(name, config);
    this.breakers.set(name, breaker);
    return breaker;
  }

  /**
   * Get all circuit breaker stats
   */
  getAllStats(): Record<string, CircuitBreakerStats> {
    const stats: Record<string, CircuitBreakerStats> = {};
    this.breakers.forEach((breaker, name) => {
      stats[name] = breaker.getStats();
    });
    return stats;
  }

  /**
   * Reset all circuit breakers
   */
  resetAll(): void {
    this.breakers.forEach(breaker => breaker.reset());
  }

  /**
   * Reset a specific circuit breaker by name
   */
  reset(name: string): void {
    const breaker = this.breakers.get(name);
    if (breaker) {
      breaker.reset();
    }
  }
}

export const circuitBreakers = new CircuitBreakerRegistry();

/**
 * Decorator for automatic circuit breaker protection
 */
export function withCircuitBreaker<T>(name: string, config?: Partial<CircuitBreakerConfig>) {
  const sanitizedName = sanitizeLogMessage(name).replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 80); // nosec CWE-78 CWE-77 CWE-88 CWE-20
  return (fn: () => Promise<T>): Promise<T> => {
    const breaker = circuitBreakers.get(sanitizedName, config);
    return breaker.execute(fn);
  };
}
